    "url": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93320#faq",
    "name": "자주 묻는 질문",
    "inLanguage": "ko-KR",
    "isPartOf": {"@id": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93320#webpage"},
    "mainEntity": [

        {
            "@type": "Question",
            "name": "\uB9AC\uC0AC\uC774\uD074 \uB2E4\uC6B4\uC774\uB780 \uBB34\uC5C7\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uAE30\uC874 \uC81C\uD488\uC5D0\uC11C \uD68C\uC218\uD55C \uB2E4\uC6B4\uC744 \uB2E4\uC2DC \uCDA9\uC804\uC7AC\uB85C \uD65C\uC6A9\uD55C \uC18C\uC7AC\uC785\uB2C8\uB2E4. \uAC89\uAC10\uC774\uB098 \uC548\uAC10\uC5D0 \uC0AC\uC6A9\uB418\uB294 \uB9AC\uC0AC\uC774\uD074 \uC6D0\uB2E8\uACFC\uB294 \uAD6C\uBD84\uB418\uBA70, \uC81C\uD488\uBCC4 \uC18C\uC7AC \uAD6C\uC131\uACFC \uC801\uC6A9 \uBD80\uC704\uB294 \uC0C1\uD488 \uC0C1\uC138\uC815\uBCF4\uC5D0\uC11C \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uBC15\uBCF4\uAC80\uC774 \uCC29\uC6A9\uD55C \uC624\uB80C\uC9C0 \uB215\uC2DC\uB294 \uC5B4\uB5A4 \uC81C\uD488\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB0A8\uC131 1996 \uB808\uD2B8\uB85C \uB215\uC2DC \uC790\uCF13(M'S 1996 RETRO NUPTSE JACKET)\uC785\uB2C8\uB2E4. \uCEEC\uB7EC\uB294 \uC624\uB80C\uC9C0(ORG), \uD488\uBC88\uC740 NJ1DS75F\uC785\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uAE30\uD68D\uC804\uC5D0\uC11C \uD568\uAED8 \uB9CC\uB098\uBCFC \uC218 \uC788\uB294 \uB2E4\uC6B4 \uC790\uCF13\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uBC15\uBCF4\uAC80\uC774 \uCC29\uC6A9\uD55C \uB0A8\uC131 1996 \uB178\uBCA8\uD2F0 \uB215\uC2DC \uC790\uCF13, \uB0A8\uC131 \uB77C\uC774\uD2B8 \uD329 \uB2E4\uC6B4 \uC790\uCF13, \uB0A8\uC131 \uD2B8\uB808\uC77C \uD329 \uB2E4\uC6B4 \uC790\uCF13\uC744 \uD568\uAED8 \uB9CC\uB098\uBCFC \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uAC01 \uC0C1\uD488 \uC0C1\uC138\uD398\uC774\uC9C0\uC5D0\uC11C \uCEEC\uB7EC\uC640 \uC0AC\uC774\uC988\uB97C \uD655\uC778\uD574 \uC8FC\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uB77C\uC774\uD2B8 \uD329 \uB2E4\uC6B4\uACFC \uD2B8\uB808\uC77C \uD329 \uB2E4\uC6B4\uC740 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB77C\uC774\uD2B8 \uD329 \uB2E4\uC6B4\uC740 \uCD08\uACBD\uB7C9 \uC18C\uC7AC\uC640 \uC554\uD640\u00B7\uC18C\uB9E4\uC758 \uD14C\uC774\uD551 \uB514\uD14C\uC77C\uC774 \uD2B9\uC9D5\uC785\uB2C8\uB2E4. \uD2B8\uB808\uC77C \uD329 \uB2E4\uC6B4\uC740 \uBCFC\uB968\uAC10 \uC788\uB294 \uC2E4\uB8E8\uC5E3\uACFC \uD3EC\uCF13 \uD50C\uB7A9 \uB514\uD14C\uC77C\uC774 \uD2B9\uC9D5\uC785\uB2C8\uB2E4. \uB450 \uC81C\uD488 \uBAA8\uB450 \uC77C\uCCB4\uD615 \uD6C4\uB4DC\uB97C \uC801\uC6A9\uD55C \uB0A8\uC131 \uB2E4\uC6B4 \uC790\uCF13\uC785\uB2C8\uB2E4"
            }
        }

    ]
}

{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "@id": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93341#faq",
    "url": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93341#faq",
    "name": "자주 묻는 질문",
    "inLanguage": "ko-KR",
    "isPartOf": {"@id": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93341#webpage"},
    "mainEntity": [

        {
            "@type": "Question",
            "name": "\uC560\uB2C8\uAC00 \uCC29\uC6A9\uD55C \uB178\uC2A4\uD398\uC774\uC2A4 \uACA8\uC6B8 \uC2E0\uBC1C\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uAE30\uD68D\uC804 \uB0B4 \uC560\uB2C8\uAC00 \uCC29\uC6A9\uD55C \uC81C\uD488\uC740 \uB178\uC2A4\uD398\uC774\uC2A4 \uC77C\uB809\uD2B8\uB860 \uC20F\uBD80\uCE20\uC785\uB2C8\uB2E4. \uC815\uD655\uD55C \uC0C9\uC0C1\uACFC \uC0AC\uC774\uC988\uB294 \uC5F0\uACB0\uB41C \uC0C1\uD488 \uC0C1\uC138\uD398\uC774\uC9C0\uC5D0\uC11C \uD655\uC778\uD574 \uC8FC\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uBBAC\uACFC \uC2AC\uB9BD\uC628\uC740 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uACA8\uC6B8 \uBBAC\uC740 \uB4A4\uAFC8\uCE58\uAC00 \uC5F4\uB9B0 \uAD6C\uC870\uB85C \uC2E0\uACE0 \uBC97\uAE30 \uAC04\uD3B8\uD569\uB2C8\uB2E4. \uC2AC\uB9BD\uC628\uC740 \uBC1C \uC804\uCCB4\uB97C \uAC10\uC2F8 \uBE44\uAD50\uC801 \uC548\uC815\uC801\uC778 \uCC29\uC6A9\uAC10\uC744 \uC81C\uACF5\uD558\uBBC0\uB85C \uD65C\uB3D9 \uD658\uACBD\uACFC \uC120\uD638\uD558\uB294 \uCC29\uD654 \uBC29\uC2DD\uC5D0 \uB530\uB77C \uC120\uD0DD\uD574 \uC8FC\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uB215\uC2DC \uBBAC\uACFC \uB215\uC2DC \uBAA9\uC740 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB215\uC2DC \uBBAC\uC740 \uAC04\uD3B8\uD558\uAC8C \uC2E0\uC744 \uC218 \uC788\uB294 \uBBAC \uD615\uD0DC\uC774\uACE0, \uB215\uC2DC \uBAA9\uC740 \uBC1C\uB4F1\uACFC \uB4A4\uAFC8\uCE58\uB97C \uAC10\uC2F8\uB294 \uB85C\uC6B0\uCEF7 \uBAA8\uD06C \uC288\uC988 \uD615\uD0DC\uC785\uB2C8\uB2E4. \uCC29\uC6A9 \uBC29\uC2DD\uACFC \uD65C\uC6A9 \uBAA9\uC801\uC5D0 \uB530\uB77C \uC120\uD0DD\uD574 \uC8FC\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uB178\uC2A4\uD398\uC774\uC2A4 \uACA8\uC6B8 \uBC29\uD55C\uD654 \uC0AC\uC774\uC988\uB294 \uC5B4\uB5BB\uAC8C \uC120\uD0DD\uD574\uC57C \uD558\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC81C\uD488\uB9C8\uB2E4 \uD615\uD0DC\uC640 \uCC29\uD654\uAC10\uC774 \uB2E4\uB97C \uC218 \uC788\uC73C\uBBC0\uB85C \uAC01 \uC0C1\uD488 \uC0C1\uC138\uD398\uC774\uC9C0\uC758 \uC0AC\uC774\uC988 \uC815\uBCF4\uB97C \uD655\uC778\uD574 \uC8FC\uC138\uC694. \uB450\uAEBC\uC6B4 \uACA8\uC6B8 \uC591\uB9D0\uACFC \uD568\uAED8 \uCC29\uC6A9\uD560 \uC608\uC815\uC774\uB77C\uBA74 \uC591\uB9D0 \uB450\uAED8\uB3C4 \uACE0\uB824\uD558\uB294 \uAC83\uC774 \uC88B\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uB178\uC2A4\uD398\uC774\uC2A4 \uBC29\uD55C\uD654\uB294 \uB208\uAE38\uC774\uB098 \uBE59\uD310\uAE38\uC5D0\uC11C\uB3C4 \uBBF8\uB044\uB7FD\uC9C0 \uC54A\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC77C\uBD80 \uC81C\uD488\uC740 \uACA8\uC6B8\uCCA0 \uB178\uBA74\uC758 \uC811\uC9C0\uB825\uC744 \uACE0\uB824\uD55C \uC544\uC6C3\uC194\uC744 \uC801\uC6A9\uD558\uC9C0\uB9CC \uBBF8\uB044\uB7EC\uC9D0\uC744 \uC644\uC804\uD788 \uBC29\uC9C0\uD558\uB294 \uAC83\uC740 \uC544\uB2D9\uB2C8\uB2E4. \uB208\uAE38, \uBE59\uD310\uAE38, \uC816\uC740 \uBC14\uB2E5\uC5D0\uC11C\uB294 \uC8FC\uC758\uD574\uC11C \uCC29\uC6A9\uD574 \uC8FC\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uACA8\uC6B8 \uBC29\uD55C\uD654\uB294 \uC5B4\uB5A4 \uAE30\uC900\uC73C\uB85C \uC120\uD0DD\uD558\uBA74 \uC88B\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uBCF4\uC628\uC131\uACFC \uC548\uC815\uC801\uC778 \uCC29\uC6A9\uC744 \uC6D0\uD55C\uB2E4\uBA74 \uC20F\uBD80\uCE20\uB97C, \uD3B8\uB9AC\uD55C \uCC29\uD654\uB97C \uC6D0\uD55C\uB2E4\uBA74 \uACA8\uC6B8 \uBBAC\uC744 \uC0B4\uD3B4\uBCF4\uC138\uC694. \uC77C\uC0C1\uACFC \uAC00\uBCBC\uC6B4 \uC57C\uC678\uD65C\uB3D9\uC5D0 \uB450\uB8E8 \uC2E0\uC744 \uC81C\uD488\uC744 \uCC3E\uB294\uB2E4\uBA74 \uC2AC\uB9BD\uC628\uC744 \uBE44\uAD50\uD574 \uBCF4\uB294 \uAC83\uC774 \uC88B\uC2B5\uB2C8\uB2E4."
            }
        }

    ]
}

{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "@id": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93344#faq",
