    "inLanguage": "ko-KR",
    "isPartOf": {"@id": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93344#webpage"},
    "mainEntity": [

        {
            "@type": "Question",
            "name": "\uB178\uC2A4\uD398\uC774\uC2A4 \uBE14\uB799\uD504\uB77C\uC774\uB370\uC774 2026\uC740 \uC5B8\uC81C\uAE4C\uC9C0 \uC9C4\uD589\uB418\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB178\uC2A4\uD398\uC774\uC2A4 \uBE14\uB799\uD504\uB77C\uC774\uB370\uC774 2026\uC740 2026\uB144 11\uC6D4 12\uC77C\uBD80\uD130 12\uC6D4 3\uC77C\uAE4C\uC9C0 \uC9C4\uD589\uB429\uB2C8\uB2E4. \uD589\uC0AC \uC77C\uC815\uACFC \uB0B4\uC6A9\uC740 \uC6B4\uC601 \uC0AC\uC815\uC5D0 \uB530\uB77C \uBCC0\uACBD\uB418\uAC70\uB098 \uC911\uB2E8\uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uBAA8\uB4E0 \uC0C1\uD488\uC774 30% \uD560\uC778\uB418\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC544\uB2C8\uC694. \uC774\uBC88 \uAE30\uD68D\uC804\uC758 \uCD5C\uB300 \uD560\uC778\uC728\uC740 30%\uC774\uBA70, \uC77C\uBD80 \uC0C1\uD488\uC740 \uD504\uB85C\uBAA8\uC158 \uB300\uC0C1\uC5D0\uC11C \uC81C\uC678\uB429\uB2C8\uB2E4. \uC0C1\uD488\uBCC4 \uD560\uC778\uC728\uACFC \uD310\uB9E4 \uAC00\uACA9\uC740 \uAC01 \uC0C1\uD488 \uC0C1\uC138 \uD398\uC774\uC9C0\uC5D0\uC11C \uD655\uC778\uD574 \uC8FC\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uC774\uBC88 \uBE14\uB799\uD504\uB77C\uC774\uB370\uC774 \uB300\uD45C \uC0C1\uD488\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB300\uD45C \uC0C1\uD488\uC740 \uB0A8\uC131 \uC368\uBC0B \uB9C8\uD14C\uD638\uB978 \uB2E4\uC6B4 \uC790\uCF13, \uC5EC\uC131 \uC5D8\uB77C \uB2E4\uC6B4 \uC790\uCF13, \uD0A4\uC988 \uD074\uB77C\uC774\uB4DC \uB2E4\uC6B4 \uC790\uCF13, \uBCF4\uB808\uC54C\uB9AC\uC2A4 \uBBF8\uB2C8 \uBC31\uD329, \uC2A4\uB178\uC6B0 \uBBAC\uC785\uB2C8\uB2E4. \uC0C9\uC0C1\uACFC \uC0AC\uC774\uC988\uBCC4 \uAD6C\uB9E4 \uAC00\uB2A5 \uC5EC\uBD80\uB294 \uC0C1\uD488 \uC0C1\uC138 \uD398\uC774\uC9C0\uC5D0\uC11C \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uD328\uB529 \uC678\uC5D0 \uC5B4\uB5A4 \uC0C1\uD488\uC744 \uC0B4\uD3B4\uBCFC \uC218 \uC788\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB2E4\uC6B4\u00B7\uD328\uB529 \uC678\uC5D0\uB3C4 \uD50C\uB9AC\uC2A4, \uC790\uCF13, \uC6A9\uD488, \uC2E0\uBC1C, \uD0A4\uC988 \uCE74\uD14C\uACE0\uB9AC\uC758 \uD589\uC0AC \uC0C1\uD488\uC744 \uC0B4\uD3B4\uBCFC \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uCE74\uD14C\uACE0\uB9AC \uB0B4 \uC0C1\uD488\uBCC4 \uD589\uC0AC \uC801\uC6A9 \uC5EC\uBD80\uB294 \uB2E4\uB97C \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        }

    ]
}

{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "@id": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93329#faq",
    "url": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93329#faq",
    "name": "자주 묻는 질문",
    "inLanguage": "ko-KR",
    "isPartOf": {"@id": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93329#webpage"},
    "mainEntity": [

        {
            "@type": "Question",
            "name": "\uC804\uC18C\uBBF8\uAC00 \uD654\uBCF4\uC5D0\uC11C \uCC29\uC6A9\uD55C \uB178\uC2A4\uD398\uC774\uC2A4 \uC5EC\uC131 \uD328\uB529\uC740 \uC5B4\uB5A4 \uC81C\uD488\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC804\uC18C\uBBF8\uAC00 \uCC29\uC6A9\uD55C \uC81C\uD488\uC740 \uB178\uC2A4\uD398\uC774\uC2A4 \uD654\uC774\uD2B8\uB77C\uBCA8\uC758 \uC5EC\uC131 \uD504\uB85C\uC81D\uD2B8 \uB2E4\uC6B4 \uC790\uCF13, \uC5EC\uC131 \uB178\uBCA8\uD2F0 \uB215\uC2DC \uC790\uCF13, \uC5EC\uC131 \uB178\uBCA8\uD2F0 \uB215\uC2DC PT \uC790\uCF13, \uC5EC\uC131 \uC5D8\uB77C \uB2E4\uC6B4 \uC790\uCF13\uC785\uB2C8\uB2E4. \uC774\uBC88 \uAE30\uD68D\uC804\uC5D0\uC11C \uB124 \uAC00\uC9C0 \uC2A4\uD0C0\uC77C\uC758 \uD654\uBCF4\uC640 \uC81C\uD488\uC744 \uD568\uAED8 \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uC5EC\uC131 \uC20F\uD328\uB529\uACFC \uD06C\uB86D \uD328\uB529\uC744 \uACE0\uB97C \uB54C \uBB34\uC5C7\uC744 \uD655\uC778\uD558\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC9E7\uC740 \uAE30\uC7A5\uC758 \uD328\uB529\uC744 \uACE0\uB97C \uB54C\uB294 \uC0C1\uD488\uBCC4 \uCD1D\uC7A5\uACFC \uC2E4\uCE21\uC744 \uD655\uC778\uD574 \uC8FC\uC138\uC694. \uC5EC\uC131 \uB178\uBCA8\uD2F0 \uB215\uC2DC\uC640 \uB178\uBCA8\uD2F0 \uB215\uC2DC PT\uB294 \uD06C\uB86D \uAE30\uC7A5\uC744 \uC801\uC6A9\uD55C \uC81C\uD488\uC774\uBA70, \uAC01 \uC0C1\uD488\uC758 \uC0C1\uC138\uC815\uBCF4\uC5D0\uC11C \uAE30\uC7A5\uACFC \uC0AC\uC774\uC988\uB97C \uBE44\uAD50\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uC2A4\uD3EC\uD2F0\uD55C \uB514\uD14C\uC77C\uC758 \uC5EC\uC131 \uB2E4\uC6B4 \uC790\uCF13\uC740 \uC5B4\uB5A4 \uC81C\uD488\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC5EC\uC131 \uD504\uB85C\uC81D\uD2B8 \uB2E4\uC6B4 \uC790\uCF13\uC740 \uC77C\uCCB4\uD615 \uD6C4\uB4DC\uC640 \uC0AC\uC120 \uC9C0\uD37C, 3\uB2E8 \uC0AC\uC120 \uD03C\uD305\uC774 \uD2B9\uC9D5\uC785\uB2C8\uB2E4. \uC2A4\uD3EC\uD2F0\uD55C \uB514\uD14C\uC77C\uC744 \uC120\uD638\uD55C\uB2E4\uBA74 \uD574\uB2F9 \uC0C1\uD488\uC758 \uD654\uBCF4\uC640 \uB514\uD14C\uC77C\uC744 \uD655\uC778\uD574 \uBCF4\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uB178\uC2A4\uD398\uC774\uC2A4 \uC5EC\uC131 \uB178\uBCA8\uD2F0 \uB215\uC2DC \uC20F\uD328\uB529\uACFC \uB178\uBCA8\uD2F0 \uB215\uC2DC PT \uC790\uCF13\uC740 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC774\uBC88 \uD654\uBCF4\uC758 \uC5EC\uC131 \uB178\uBCA8\uD2F0 \uB215\uC2DC \uC790\uCF13\uC740 \uC138\uBBF8 \uD06C\uB86D \uAE30\uC7A5\uACFC \uCEE4\uD53C\uBE0C\uB77C\uC6B4 \uCEEC\uB7EC\uAC00 \uB3CB\uBCF4\uC774\uB294 \uC20F\uD328\uB529\uC785\uB2C8\uB2E4. \uC5EC\uC131 \uB178\uBCA8\uD2F0 \uB215\uC2DC PT \uC790\uCF13\uC740 \uC544\uC774\uBCF4\uB9AC \uCCB4\uD06C \uD328\uD134\uC73C\uB85C \uBE48\uD2F0\uC9C0\uD55C \uBD84\uC704\uAE30\uB97C \uB354\uD55C \uC81C\uD488\uC785\uB2C8\uB2E4. \uCC28\uBD84\uD55C \uCEEC\uB7EC\uC640 \uCCB4\uD06C \uD328\uD134 \uC911 \uC6D0\uD558\uB294 \uC2A4\uD0C0\uC77C\uC5D0 \uB530\uB77C \uC120\uD0DD\uD574 \uBCF4\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uC804\uC18C\uBBF8\uAC00 \uCC29\uC6A9\uD55C \uAD11\uD0DD \uC788\uB294 \uC5EC\uC131 \uD328\uB529\uC740 \uC5B4\uB5A4 \uC81C\uD488\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC804\uC18C\uBBF8\uAC00 \uD1A0\uD504 \uCEEC\uB7EC\uB85C \uCC29\uC6A9\uD55C \uC81C\uD488\uC740 \uC5EC\uC131 \uC5D8\uB77C \uB2E4\uC6B4 \uC790\uCF13(W'S ELLA DOWN JACKET)\uC785\uB2C8\uB2E4. \uAD11\uD0DD\uACFC \uC154\uB9C1 \uB514\uD14C\uC77C\uC774 \uB3CB\uBCF4\uC774\uB294 \uB178\uC2A4\uD398\uC774\uC2A4 \uD654\uC774\uD2B8\uB77C\uBCA8 \uC5EC\uC131 \uB2E4\uC6B4 \uC790\uCF13\uC73C\uB85C, \uC720\uAD11 \uD328\uB529 \uC2A4\uD0C0\uC77C\uC744 \uCC3E\uB294 \uBD84\uAED8 \uC81C\uC548\uD569\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uB178\uC2A4\uD398\uC774\uC2A4 \uC5EC\uC131 \uD328\uB529 \uC0AC\uC774\uC988\uB294 \uC5B4\uB5BB\uAC8C \uC120\uD0DD\uD558\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC0C1\uD488 \uC0C1\uC138\uD398\uC774\uC9C0\uC758 \uC0AC\uC774\uC988 \uC548\uB0B4\uC640 \uC2E4\uCE21 \uC815\uBCF4\uB97C \uD655\uC778\uD558\uACE0, \uD3C9\uC18C \uD3B8\uD558\uAC8C \uC785\uB294 \uC544\uC6B0\uD130\uC640 \uBE44\uAD50\uD574 \uC120\uD0DD\uD574 \uC8FC\uC138\uC694. \uB2C8\uD2B8\uB098 \uD6C4\uB4DC\uD2F0\uB97C \uD568\uAED8 \uC785\uB294\uB2E4\uBA74 \uAC00\uC2B4\uB458\uB808\uC640 \uC18C\uB9E4\uC758 \uC5EC\uC720\uB3C4 \uC0B4\uD3B4\uBCF4\uC138\uC694. \uAC19\uC740 \uC0AC\uC774\uC988\uB77C\uB3C4 \uC81C\uD488\uBCC4 \uAE30\uC7A5\uACFC \uC2E4\uB8E8\uC5E3\uC5D0 \uB530\uB77C \uCC29\uC6A9\uAC10\uC774 \uB2EC\uB77C\uC9C8 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        }

    ]
}

