    "mainEntity": [

        {
            "@type": "Question",
            "name": "\uBC15\uBCF4\uAC80\u00B7\uAE40\uB098\uC601\u00B7\uC804\uC18C\uBBF8\u00B7\uC774\uD638\uC5F0\uC774 \uCC29\uC6A9\uD55C \uACA8\uC6B8 \uBC29\uD55C\uC6A9\uD488\uC740 \uC5B4\uB514\uC5D0\uC11C \uBCFC \uC218 \uC788\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC774 \uAE30\uD68D\uC804\uC5D0\uC11C \uBC15\uBCF4\uAC80\u00B7\uAE40\uB098\uC601\u00B7\uC804\uC18C\uBBF8\u00B7\uC774\uD638\uC5F0\uC758 \uCC29\uC7A5\uACFC \uD568\uAED8 \uB178\uC2A4\uD398\uC774\uC2A4 \uACA8\uC6B8 \uBC29\uD55C\uC6A9\uD488\uC744 \uB9CC\uB098\uBCFC \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uBE44\uB2C8\uC640 \uBC29\uD55C \uBAA8\uC790, \uC7A5\uAC11 \uB4F1 \uD654\uBCF4\uC5D0 \uC5F0\uACB0\uB41C \uC0C1\uD488\uC5D0\uC11C \uB3D9\uC77C\uD55C \uCEEC\uB7EC\uC640 \uC0C1\uC138 \uC815\uBCF4\uB97C \uD655\uC778\uD574 \uC8FC\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uACA8\uC6B8 \uBE44\uB2C8\uB294 \uC5B4\uB5A4 \uAE30\uC900\uC73C\uB85C \uACE0\uB974\uBA74 \uC88B\uC744\uAE4C\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC18C\uC7AC\uC640 \uD54F, \uB514\uC790\uC778\uC744 \uAE30\uC900\uC73C\uB85C \uC0B4\uD3B4\uBCF4\uC138\uC694. \uD3EC\uADFC\uD55C \uC6B8\uACFC \uD50C\uB9AC\uC2A4 \uC18C\uC7AC\uBD80\uD130 \uBCA0\uC774\uC9C1\uD55C \uB2C8\uD2B8, \uB85C\uACE0\u00B7\uB808\uD130\uB9C1 \uB514\uC790\uC778\uAE4C\uC9C0 \uB2E4\uC591\uD558\uAC8C \uAD6C\uC131\uB418\uC5B4 \uC788\uC5B4 \uB370\uC77C\uB9AC \uC2A4\uD0C0\uC77C\uC774\uB098 \uC544\uC6C3\uB3C4\uC5B4 \uD65C\uB3D9\uC5D0 \uB9DE\uCDB0 \uC120\uD0DD\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uC774\uC5B4\uBA38\uD504 \uCEA1\uACFC \uC77C\uBC18 \uACA8\uC6B8 \uBAA8\uC790\uB294 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC774\uC5B4\uBA38\uD504 \uCEA1\uC740 \uADC0\uB97C \uAC10\uC2F8\uB294 \uADC0\uB2EC\uC774 \uB514\uD14C\uC77C\uC744 \uC801\uC6A9\uD574 \uCD94\uC6B4 \uB0A0\uC528\uC5D0 \uBCF4\uC628\uC131\uC744 \uB192\uC778 \uBC29\uD55C \uBAA8\uC790\uC785\uB2C8\uB2E4. \uD50C\uB9AC\uC2A4\u00B7\uD328\uB529\u00B7\uB2E4\uC6B4 \uB4F1 \uC18C\uC7AC\uAC00 \uB2E4\uC591\uD558\uBA70, \uC77C\uBC18 \uCEA1\uC774\uB098 \uBC84\uD0B7\uD587 \uD615\uD0DC\uC758 \uBC29\uD55C \uBAA8\uC790\uB3C4 \uC788\uC73C\uBBC0\uB85C \uC6D0\uD558\uB294 \uCC29\uC6A9 \uBC29\uC2DD\uACFC \uB514\uC790\uC778\uC5D0 \uB9DE\uCDB0 \uBE44\uAD50\uD574 \uBCF4\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uACA8\uC6B8 \uC7A5\uAC11\uC744 \uACE0\uB97C \uB54C \uC5B4\uB5A4 \uAE30\uB2A5\uC744 \uD655\uC778\uD558\uBA74 \uC88B\uC744\uAE4C\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uBCF4\uC628 \uC18C\uC7AC\uC640 \uCC29\uC6A9\uAC10, \uD65C\uB3D9\uC5D0 \uD544\uC694\uD55C \uAE30\uB2A5\uC744 \uD655\uC778\uD574 \uC8FC\uC138\uC694. \uD50C\uB9AC\uC2A4 \uC18C\uC7AC\uC758 \uC7A5\uAC11\uBD80\uD130 \uBC29\uD48D \uB514\uD14C\uC77C\uACFC \uC2A4\uB9C8\uD2B8 \uD130\uCE58 \uAE30\uB2A5\uC744 \uAC16\uCD98 \uC81C\uD488\uAE4C\uC9C0 \uC788\uC5B4 \uC77C\uC0C1\uC0DD\uD65C\uACFC \uC57C\uC678 \uD65C\uB3D9\uC5D0 \uB9DE\uCDB0 \uC120\uD0DD\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uBAA9\uB3C4\uB9AC\u00B7\uBAA9 \uC6CC\uBA38\u00B7\uBC14\uB77C\uD074\uB77C\uBC14\u00B7\uADC0\uB9C8\uAC1C\uB294 \uC5B4\uB5BB\uAC8C \uC120\uD0DD\uD558\uBA74 \uC88B\uC744\uAE4C\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB530\uB73B\uD558\uAC8C \uBCF4\uD638\uD558\uACE0 \uC2F6\uC740 \uBD80\uC704\uC640 \uD65C\uB3D9 \uD658\uACBD\uC5D0 \uB530\uB77C \uC120\uD0DD\uD574 \uBCF4\uC138\uC694. \uBAA9\uC744 \uAC10\uC2F8\uB294 \uBA38\uD50C\uB7EC\uC640 \uBAA9 \uC6CC\uBA38(\uB125\uAC8C\uC774\uD130), \uADC0\uB97C \uBCF4\uD638\uD558\uB294 \uADC0\uB9C8\uAC1C, \uC5BC\uAD74\uACFC \uBAA9\uAE4C\uC9C0 \uD3ED\uB113\uAC8C \uAC10\uC2F8\uB294 \uBC14\uB77C\uD074\uB77C\uBC14 \uB4F1 \uCC29\uC6A9 \uBC94\uC704\uC640 \uD615\uD0DC\uAC00 \uC11C\uB85C \uB2E4\uB985\uB2C8\uB2E4"
            }
        },


        {
            "@type": "Question",
            "name": "\uACA8\uC6B8 \uBC29\uD55C\uC6A9\uD488\uC740 \uC5B4\uB5A4 \uAE30\uC900\uC73C\uB85C \uACE0\uB974\uBA74 \uC88B\uC744\uAE4C\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uD3C9\uC18C \uD65C\uB3D9\uACFC \uD544\uC694\uD55C \uBCF4\uC628 \uBD80\uC704\uB97C \uBA3C\uC800 \uD655\uC778\uD574 \uBCF4\uC138\uC694. \uC77C\uC0C1\uC5D0\uC11C\uB294 \uBE44\uB2C8\u00B7\uBA38\uD50C\uB7EC\u00B7\uADC0\uB9C8\uAC1C\uCC98\uB7FC \uAC04\uD3B8\uD55C \uC544\uC774\uD15C\uC744, \uACA8\uC6B8 \uC5EC\uD589\uC774\uB098 \uCEA0\uD551\u00B7\uC544\uC6C3\uB3C4\uC5B4\uC5D0\uC11C\uB294 \uC774\uC5B4\uBA38\uD504 \uCEA1\u00B7\uC7A5\uAC11\u00B7\uBAA9 \uC6CC\uBA38\u00B7\uBC14\uB77C\uD074\uB77C\uBC14 \uB4F1 \uBCF4\uC628 \uBC94\uC704\uAC00 \uB113\uC740 \uC544\uC774\uD15C\uC744 \uBE44\uAD50\uD574 \uC120\uD0DD\uD558\uB294 \uAC83\uC774 \uC88B\uC2B5\uB2C8\uB2E4."
            }
        }

    ]
}

